/*
 * LPC2148 SmartX Board - 4-LED Binary Counter
 * Counts from 0 to 15 on onboard LEDs (P0.12-P0.15)
 * No external wiring required!
 */

#include <LPC214x.h>

int main() {
    // Set P0.12-P0.15 as outputs (LED1-LED4)
    IO0DIR |= (1 << 12) | (1 << 13) | (1 << 14) | (1 << 15);
    int count = 0;
    while (1) {
        IO0CLR = 0xF << 12;              // Clear all 4 LEDs
        IO0SET = (count & 0xF) << 12;    // Set current count pattern
        delay_ms(500);
        count = (count + 1) & 0xF;       // Increment, wrap at 16
    }
}
